-- Campagne étirée de 9 à 15 chapitres, même difficulté de départ et
-- d'arrivée : chaque étage se place sur la courbe de référence de 90 étages
-- (`curvePosition`, campaign.definitions.ts). Les étages normaux sont
-- refittés au simulateur sur les 150 étages réels, les boss aussi.
--
-- Progression des joueurs CONSERVÉE (chapitre-étage) : un joueur à 5-1 reste
-- à 5-1, sur une difficulté plus douce. Le total du butin est celui de la
-- campagne de 9 chapitres (premiers passages ×81/135, boss répartis, même
-- nombre de pièces et de cartes garanties). Les chapitres 1 à 8 gardent leurs
-- monstres ; 9 à 14 sont nouveaux, le 15 reprend l'ancien chapitre final.
--
-- Succès : « Au bout de la Faille » passe au chapitre 15, un nouveau au
-- chapitre 12, celui du chapitre 9 prend le nom du nouveau chapitre 9.
--
-- Migration de DONNÉES (le déploiement ne seede jamais), générée depuis les
-- définitions. Idempotente : upsert sur (chapter, index), succès créés s'ils
-- manquent.

ON CONFLICT (chapter, "index") DO UPDATE SET
  "labelFr" = EXCLUDED."labelFr",
  "labelEn" = EXCLUDED."labelEn",
  "isBoss" = EXCLUDED."isBoss",
  "enemyTeam" = EXCLUDED."enemyTeam",
  "lootTable" = EXCLUDED."lootTable",
  "order" = EXCLUDED."order";

UPDATE "Achievement"
SET "nameFr" = 'Marais', "nameEn" = 'Marsh', tier = 3
WHERE key = 'chapter_reached_9';

UPDATE "Rewards"
SET tokens = 12, dust = 300, xp = 0, "cardRarity" = 'RARE'::"CardRarity"
WHERE id = (SELECT "rewardId" FROM "Achievement" WHERE key = 'chapter_reached_9');

WITH r AS (
  SELECT gen_random_uuid()::text, 15, 400, 0, 'RARE'::"CardRarity"
  WHERE NOT EXISTS (SELECT 1 FROM "Achievement" WHERE key = 'chapter_reached_12')
  RETURNING id
)
SELECT gen_random_uuid()::text, 'chapter_reached_12', 'Cimes', 'Peaks', 'Atteindre le chapitre 12.', 'Reach chapter 12.', 'campaign', 3, false, '{"type":"CAMPAIGN_CHAPTER_REACHED","threshold":12}'::jsonb, 12, true, r.id
FROM r;

WITH r AS (
  SELECT gen_random_uuid()::text, 25, 600, 0, 'EPIC'::"CardRarity"
  WHERE NOT EXISTS (SELECT 1 FROM "Achievement" WHERE key = 'chapter_reached_15')
  RETURNING id
)
SELECT gen_random_uuid()::text, 'chapter_reached_15', 'Au bout de la Faille', 'The Edge of the Rift', 'Atteindre le chapitre 15.', 'Reach chapter 15.', 'campaign', 4, false, '{"type":"CAMPAIGN_CHAPTER_REACHED","threshold":15}'::jsonb, 13, true, r.id
FROM r;
